-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_League AS SELECT League.id AS id, League.country_id AS country_id, League.name AS name, country.name AS country_name FROM League LEFT JOIN Country AS country ON League.country_id = country.id;

-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_Player_Attributes AS SELECT Player_Attributes.id AS id, Player_Attributes.player_fifa_api_id AS player_fifa_api_id, Player_Attributes.player_api_id AS player_api_id, Player_Attributes.date AS date, Player_Attributes.overall_rating AS overall_rating, Player_Attributes.potential AS potential, Player_Attributes.preferred_foot AS preferred_foot, Player_Attributes.attacking_work_rate AS attacking_work_rate, Player_Attributes.defensive_work_rate AS defensive_work_rate, Player_Attributes.crossing AS crossing, Player_Attributes.finishing AS finishing, Player_Attributes.heading_accuracy AS heading_accuracy, Player_Attributes.short_passing AS short_passing, Player_Attributes.volleys AS volleys, Player_Attributes.dribbling AS dribbling, Player_Attributes.curve AS curve, Player_Attributes.free_kick_accuracy AS free_kick_accuracy, Player_Attributes.long_passing AS long_passing, Player_Attributes.ball_control AS ball_control, Player_Attributes.acceleration AS acceleration, Player_Attributes.sprint_speed AS sprint_speed, Player_Attributes.agility AS agility, Player_Attributes.reactions AS reactions, Player_Attributes.balance AS balance, Player_Attributes.shot_power AS shot_power, Player_Attributes.jumping AS jumping, Player_Attributes.stamina AS stamina, Player_Attributes.strength AS strength, Player_Attributes.long_shots AS long_shots, Player_Attributes.aggression AS aggression, Player_Attributes.interceptions AS interceptions, Player_Attributes.positioning AS positioning, Player_Attributes.vision AS vision, Player_Attributes.penalties AS penalties, Player_Attributes.marking AS marking, Player_Attributes.standing_tackle AS standing_tackle, Player_Attributes.sliding_tackle AS sliding_tackle, Player_Attributes.gk_diving AS gk_diving, Player_Attributes.gk_handling AS gk_handling, Player_Attributes.gk_kicking AS gk_kicking, Player_Attributes.gk_positioning AS gk_positioning, Player_Attributes.gk_reflexes AS gk_reflexes, player_api.id AS player_api_id_2, player_api.player_name AS player_api_player_name, player_api.player_fifa_api_id AS player_api_player_fifa_api_id, player_api.birthday AS player_api_birthday, player_api.height AS player_api_height, player_api.weight AS player_api_weight, player_fifa_api.id AS player_fifa_api_id_2, player_fifa_api.player_api_id AS player_fifa_api_player_api_id, player_fifa_api.player_name AS player_fifa_api_player_name, player_fifa_api.birthday AS player_fifa_api_birthday, player_fifa_api.height AS player_fifa_api_height, player_fifa_api.weight AS player_fifa_api_weight FROM Player_Attributes LEFT JOIN Player AS player_api ON Player_Attributes.player_api_id = player_api.player_api_id LEFT JOIN Player AS player_fifa_api ON Player_Attributes.player_fifa_api_id = player_fifa_api.player_fifa_api_id;

-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_Team_Attributes AS SELECT Team_Attributes.id AS id, Team_Attributes.team_fifa_api_id AS team_fifa_api_id, Team_Attributes.team_api_id AS team_api_id, Team_Attributes.date AS date, Team_Attributes.buildUpPlaySpeed AS buildUpPlaySpeed, Team_Attributes.buildUpPlaySpeedClass AS buildUpPlaySpeedClass, Team_Attributes.buildUpPlayDribbling AS buildUpPlayDribbling, Team_Attributes.buildUpPlayDribblingClass AS buildUpPlayDribblingClass, Team_Attributes.buildUpPlayPassing AS buildUpPlayPassing, Team_Attributes.buildUpPlayPassingClass AS buildUpPlayPassingClass, Team_Attributes.buildUpPlayPositioningClass AS buildUpPlayPositioningClass, Team_Attributes.chanceCreationPassing AS chanceCreationPassing, Team_Attributes.chanceCreationPassingClass AS chanceCreationPassingClass, Team_Attributes.chanceCreationCrossing AS chanceCreationCrossing, Team_Attributes.chanceCreationCrossingClass AS chanceCreationCrossingClass, Team_Attributes.chanceCreationShooting AS chanceCreationShooting, Team_Attributes.chanceCreationShootingClass AS chanceCreationShootingClass, Team_Attributes.chanceCreationPositioningClass AS chanceCreationPositioningClass, Team_Attributes.defencePressure AS defencePressure, Team_Attributes.defencePressureClass AS defencePressureClass, Team_Attributes.defenceAggression AS defenceAggression, Team_Attributes.defenceAggressionClass AS defenceAggressionClass, Team_Attributes.defenceTeamWidth AS defenceTeamWidth, Team_Attributes.defenceTeamWidthClass AS defenceTeamWidthClass, Team_Attributes.defenceDefenderLineClass AS defenceDefenderLineClass, team_api.id AS team_api_id_2, team_api.team_fifa_api_id AS team_api_team_fifa_api_id, team_api.team_long_name AS team_api_team_long_name, team_api.team_short_name AS team_api_team_short_name FROM Team_Attributes LEFT JOIN Team AS team_api ON Team_Attributes.team_api_id = team_api.team_api_id;
